schema:
CREATE TABLE book_language (
  language_code,
  language_id,
  language_name
);

CREATE TABLE customer (
  customer_id,
  email,
  first_name,
  last_name
);

CREATE TABLE customer_address (
  address_id,
  customer_id,
  status_id
);

CREATE TABLE order_history (
  history_id,
  order_id,
  status_date,
  status_id
);

CREATE TABLE order_line (
  book_id,
  line_id,
  order_id,
  price
);

CREATE TABLE shipping_method (
  cost,
  method_id,
  method_name
);
